  \draw[ink] (2.15,0) -- (3,1.7) -- (3.85,0);
  \node[below, font=\small] at (3,-0.722) {b)};
  \draw[ink] (6,0.82) circle (0.82);
  \draw[ink] (5.18,0.82) arc (180:360:0.82 and 0.246);
  \draw[ink, dashed] (5.18,0.82) arc (180:0:0.82 and 0.246);
  \node[below, font=\small] at (6,-0.45) {c)};
